    22→  const formatTime = (dateStr: string): string => {
    23→    const date = new Date(dateStr);
    24→    const now = new Date();
    25→    const diffMs = now.getTime() - date.getTime();
    26→    const diffMins = Math.floor(diffMs / 60000);
    27→    const diffHours = Math.floor(diffMins / 60);
    28→    const diffDays = Math.floor(diffHours / 24);
    29→
    30→    if (diffMins < 1) return t("office.justNow");
    31→    if (diffMins < 60) return t("office.minutesAgo", { count: diffMins });
    32→    if (diffHours < 24) return t("office.hoursAgo", { count: diffHours });
    33→    return t("office.daysAgo", { count: diffDays });
    34→  };
    35→
