    41→    e.stopPropagation();
    42→    if (confirm(t("office.deleteConfirm", { name: project.projectName }))) {
    43→      onDelete(project.projectDir);
    44→    }
    45→  };
    46→
    47→  return (
    48→    <div
    49→      className="bg-card border border-border rounded-lg p-4 cursor-pointer hover:border-primary/50 transition-colors"
